package io.github.miclean.tests;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
import io.github.miclean.module.skip.*;
/** Tests explicit route selection without changing service or authorization method. */
public final class SkipInputModeUiSmoke extends Instrumentation {
 private Activity current;private int checks;
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void callActivityOnResume(Activity a){super.callActivityOnResume(a);current=a;}
 private void check(boolean v,String s){checks++;if(!v)throw new AssertionError(s);}
 private void main(Runnable r){Throwable[] e={null};runOnMainSync(()->{try{r.run();}catch(Throwable x){e[0]=x;}});if(e[0]!=null)throw new AssertionError(e[0]);}
 private View tag(View v,String k){if(k.equals(v.getTag()))return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View f=tag(((ViewGroup)v).getChildAt(i),k);if(f!=null)return f;}return null;}
 private AlertDialog dialog(String key){try{java.lang.reflect.Field f=current.getClass().getDeclaredField("smartSkip");f.setAccessible(true);Object panel=f.get(current);f=panel.getClass().getDeclaredField(key);f.setAccessible(true);return(AlertDialog)f.get(panel);}catch(Exception e){throw new AssertionError(e);}}
 private void open(){main(()->tag(current.getWindow().getDecorView(),"skip_access_method").performClick());waitForIdleSync();main(()->{AlertDialog d=dialog("methodDialog");check(d.isShowing(),"Method picker missing");check(d.getListView().getCount()==2,"Root/Shizuku choices changed");d.getButton(AlertDialog.BUTTON_NEUTRAL).performClick();});waitForIdleSync();main(()->check(dialog("inputRouteDialog").getListView().getCount()==4,"Comparison options missing"));}
 private void capture(){main(()->{View v=dialog("inputRouteDialog").getWindow().getDecorView();android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(v.getWidth(),v.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);v.draw(new android.graphics.Canvas(b));try(java.io.FileOutputStream out=new java.io.FileOutputStream(new java.io.File(getTargetContext().getCacheDir(),"input-comparison-dialog-01212.png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}catch(Exception e){throw new AssertionError(e);}finally{b.recycle();}});}
 @Override public void onStart(){Bundle out=new Bundle();SharedPreferences p=getTargetContext().getSharedPreferences("smart_skip",0),ui=getTargetContext().getSharedPreferences("miclean_ui",0);Map<String,?> before=new HashMap<>(p.getAll()),ub=new HashMap<>(ui.getAll());
 try{for(int i=0;i<80&&current==null;i++)SystemClock.sleep(100);check(current!=null,"Main not opened");SystemClock.sleep(500);main(()->{View root=current.getWindow().getDecorView();for(String key:new String[]{"advertising","smart_skip","skip_compact_settings"})if(tag(root,"body:"+key).getVisibility()!=View.VISIBLE)tag(root,"fold:"+key).performClick();});
  int original=SkipInputMode.normalize(p.getInt(SkipInputMode.KEY,0));open();main(()->{check(dialog("inputRouteDialog").getListView().getCheckedItemPosition()==original,"Existing route lost");dialog("inputRouteDialog").getButton(-2).performClick();});waitForIdleSync();check(p.contains(SkipInputMode.KEY)==before.containsKey(SkipInputMode.KEY),"Cancel wrote a default key");
  for(int mode:new int[]{1,2,3,0}){open();final int selected=mode;main(()->{ListView list=dialog("inputRouteDialog").getListView();list.performItemClick(list.getChildAt(selected),selected,list.getAdapter().getItemId(selected));});waitForIdleSync();check(p.getInt(SkipInputMode.KEY,-1)==mode,"Choice not saved");check(Objects.equals(before.get("access_method"),p.getAll().get("access_method")),"Input choice changed Root/Shizuku");check(Objects.equals(before.get("enabled"),p.getAll().get("enabled")),"Input choice changed master");open();main(()->check(dialog("inputRouteDialog").getListView().getCheckedItemPosition()==selected,"Reopen lost chosen route"));capture();main(()->dialog("inputRouteDialog").getButton(-2).performClick());waitForIdleSync();}
  out.putString("stream","PASS: "+checks+" input comparison UI checks; original Root/Shizuku choices, cancel without writing, explicit selection, reopen, restoration and independent master/method.\n");
 }catch(Throwable e){out.putString("stream","FAIL: "+e+"\n");}finally{if(current!=null)main(()->{for(String k:new String[]{"methodDialog","inputRouteDialog"}){AlertDialog d=dialog(k);if(d!=null)d.dismiss();}});SharedPreferences.Editor e=p.edit();if(before.containsKey(SkipInputMode.KEY))e.putInt(SkipInputMode.KEY,(Integer)before.get(SkipInputMode.KEY));else e.remove(SkipInputMode.KEY);e.commit();e=ui.edit();for(String k:new String[]{"advertising","smart_skip","skip_compact_settings"}){if(ub.containsKey(k))e.putBoolean(k,(Boolean)ub.get(k));else e.remove(k);}e.commit();}
 finish(out.getString("stream","").startsWith("PASS:")?Activity.RESULT_OK:Activity.RESULT_CANCELED,out);}
}
